-- Etapa 10.7: cortes financieros.
-- Migration is incremental. It does not update or delete existing business rows.
BEGIN;

-- Canonical workflow states. IDs are generated by the database and resolved by name.
INSERT INTO "estados_corte" ("nombre", "descripcion")
VALUES
  ('En preparación', 'Corte creado; permite revisar pagos antes de generar los detalles.'),
  ('Abierto', 'Corte generado; sus detalles pueden consultarse y el corte puede cerrarse o cancelarse.'),
  ('Cerrado', 'Corte cerrado; estado terminal e inmutable.'),
  ('Cancelado', 'Corte cancelado; estado terminal, conserva detalles y libera sus reservas.')
ON CONFLICT ("nombre") DO NOTHING;

-- Abort before adding constraints/reservations if existing rows conflict with the new invariants.
DO $$
BEGIN
  IF EXISTS (
    SELECT 1 FROM "cortes_financieros"
    GROUP BY "numero_corte" HAVING COUNT(*) > 1
  ) THEN
    RAISE EXCEPTION 'Etapa 10.7: existen numero_corte duplicados; no se aplicó la migración.';
  END IF;

  IF EXISTS (
    SELECT 1
    FROM "cortes_financieros" c
    JOIN "estados_corte" e ON e."id" = c."estado_id"
    WHERE e."nombre" <> 'Cancelado'
      AND (
        EXTRACT(ISODOW FROM (c."fecha_inicio" AT TIME ZONE 'America/Cancun')) <> 5
        OR (c."fecha_inicio" AT TIME ZONE 'America/Cancun')::time <> TIME '00:00:00'
        OR NOT (
          (c."fecha_fin" AT TIME ZONE 'America/Cancun') = ((c."fecha_inicio" AT TIME ZONE 'America/Cancun')::date + 7)::timestamp
          OR (c."fecha_fin" AT TIME ZONE 'America/Cancun') = ((c."fecha_inicio" AT TIME ZONE 'America/Cancun')::date + 6) + TIME '23:59:59'
        )
      )
  ) THEN
    RAISE EXCEPTION 'Etapa 10.7: existen cortes activos que no usan semanas viernes-jueves semiabiertas; revisa los periodos antes de migrar.';
  END IF;

  IF EXISTS (
    SELECT (c."fecha_inicio" AT TIME ZONE 'America/Cancun')::date
    FROM "cortes_financieros" c
    JOIN "estados_corte" e ON e."id" = c."estado_id"
    WHERE e."nombre" <> 'Cancelado'
    GROUP BY (c."fecha_inicio" AT TIME ZONE 'America/Cancun')::date
    HAVING COUNT(*) > 1
  ) THEN
    RAISE EXCEPTION 'Etapa 10.7: existen varios cortes no cancelados para el mismo periodo semanal.';
  END IF;

  IF EXISTS (
    SELECT d."pago_id"
    FROM "detalle_corte" d
    JOIN "cortes_financieros" c ON c."id" = d."corte_id"
    JOIN "estados_corte" e ON e."id" = c."estado_id"
    WHERE e."nombre" <> 'Cancelado'
    GROUP BY d."pago_id"
    HAVING COUNT(*) > 1
  ) THEN
    RAISE EXCEPTION 'Etapa 10.7: un pago aparece en más de un corte no cancelado.';
  END IF;
END $$;

-- Preserve unique, never-reused global numbering under concurrent requests.
CREATE SEQUENCE "cortes_financieros_numero_corte_seq" AS INTEGER START WITH 1 INCREMENT BY 1 NO MINVALUE NO MAXVALUE CACHE 1;
SELECT setval(
  '"cortes_financieros_numero_corte_seq"',
  COALESCE((SELECT MAX("numero_corte") + 1 FROM "cortes_financieros"), 1),
  false
);
ALTER TABLE "cortes_financieros"
  ALTER COLUMN "numero_corte" SET DEFAULT nextval('"cortes_financieros_numero_corte_seq"');
ALTER SEQUENCE "cortes_financieros_numero_corte_seq"
  OWNED BY "cortes_financieros"."numero_corte";
CREATE UNIQUE INDEX "uq_cortes_numero_corte"
  ON "cortes_financieros"("numero_corte");
CREATE INDEX "ix_cortes_estado_fecha"
  ON "cortes_financieros"("estado_id", "fecha_inicio");
CREATE INDEX "ix_cortes_periodo"
  ON "cortes_financieros"("fecha_inicio", "fecha_fin");

-- Unique active-period reservation. Deletion of this reservation on cancel permits reuse;
-- the cancelled cut and its details remain untouched.
CREATE TABLE "cortes_periodos_reservados" (
  "periodo_inicio" DATE NOT NULL,
  "corte_id" UUID NOT NULL,
  CONSTRAINT "cortes_periodos_reservados_pkey" PRIMARY KEY ("periodo_inicio"),
  CONSTRAINT "uq_cortes_periodo_reservado_corte" UNIQUE ("corte_id")
);
ALTER TABLE "cortes_periodos_reservados"
  ADD CONSTRAINT "fk_cortes_periodo_reservado"
  FOREIGN KEY ("corte_id") REFERENCES "cortes_financieros"("id")
  ON DELETE NO ACTION ON UPDATE NO ACTION;
INSERT INTO "cortes_periodos_reservados" ("periodo_inicio", "corte_id")
SELECT (c."fecha_inicio" AT TIME ZONE 'America/Cancun')::date, c."id"
FROM "cortes_financieros" c
JOIN "estados_corte" e ON e."id" = c."estado_id"
WHERE e."nombre" <> 'Cancelado';

-- One payment may be claimed by one non-cancelled cut; cancellation releases only this claim.
CREATE TABLE "cortes_pagos_reservados" (
  "pago_id" UUID NOT NULL,
  "corte_id" UUID NOT NULL,
  CONSTRAINT "cortes_pagos_reservados_pkey" PRIMARY KEY ("pago_id")
);
CREATE INDEX "ix_cortes_pagos_reservados_corte"
  ON "cortes_pagos_reservados"("corte_id");
ALTER TABLE "cortes_pagos_reservados"
  ADD CONSTRAINT "fk_cortes_pago_reservado_pago"
  FOREIGN KEY ("pago_id") REFERENCES "pagos"("id")
  ON DELETE NO ACTION ON UPDATE NO ACTION,
  ADD CONSTRAINT "fk_cortes_pago_reservado_corte"
  FOREIGN KEY ("corte_id") REFERENCES "cortes_financieros"("id")
  ON DELETE NO ACTION ON UPDATE NO ACTION;
INSERT INTO "cortes_pagos_reservados" ("pago_id", "corte_id")
SELECT d."pago_id", d."corte_id"
FROM "detalle_corte" d
JOIN "cortes_financieros" c ON c."id" = d."corte_id"
JOIN "estados_corte" e ON e."id" = c."estado_id"
WHERE e."nombre" <> 'Cancelado';

-- Immutable audit history for state transitions.
CREATE TABLE "historial_estados_corte" (
  "id" UUID NOT NULL DEFAULT gen_random_uuid(),
  "corte_id" UUID NOT NULL,
  "estado_anterior_id" SMALLINT,
  "estado_nuevo_id" SMALLINT NOT NULL,
  "cambiado_por" UUID NOT NULL,
  "fecha_cambio" TIMESTAMPTZ(6) NOT NULL DEFAULT CURRENT_TIMESTAMP,
  "comentario" TEXT,
  CONSTRAINT "historial_estados_corte_pkey" PRIMARY KEY ("id")
);
CREATE INDEX "ix_historial_estado_corte_fecha"
  ON "historial_estados_corte"("corte_id", "fecha_cambio");
ALTER TABLE "historial_estados_corte"
  ADD CONSTRAINT "fk_historial_estado_corte"
    FOREIGN KEY ("corte_id") REFERENCES "cortes_financieros"("id") ON DELETE NO ACTION ON UPDATE NO ACTION,
  ADD CONSTRAINT "fk_historial_estado_corte_anterior"
    FOREIGN KEY ("estado_anterior_id") REFERENCES "estados_corte"("id") ON DELETE NO ACTION ON UPDATE NO ACTION,
  ADD CONSTRAINT "fk_historial_estado_corte_nuevo"
    FOREIGN KEY ("estado_nuevo_id") REFERENCES "estados_corte"("id") ON DELETE NO ACTION ON UPDATE NO ACTION,
  ADD CONSTRAINT "fk_historial_estado_corte_usuario"
    FOREIGN KEY ("cambiado_por") REFERENCES "usuarios"("id") ON DELETE NO ACTION ON UPDATE NO ACTION;

-- A corte must never cascade-delete its historical payment details.
ALTER TABLE "detalle_corte" DROP CONSTRAINT "fk_detalle_corte";
ALTER TABLE "detalle_corte"
  ADD CONSTRAINT "fk_detalle_corte"
  FOREIGN KEY ("corte_id") REFERENCES "cortes_financieros"("id")
  ON DELETE NO ACTION ON UPDATE NO ACTION;

COMMIT;
